export class SqlIdentityRepository {
  constructor(db) { if (!db) throw new IdentityError('PERSISTENT_STORAGE_NOT_CONFIGURED', 503); this.db = db }
  async one(sql,p=[]) { const q=this.db.prepare(sql); const bound=typeof q.bind==='function'; const b=bound?q.bind(...p):q; return (await (b.first?b.first():b.get(...(bound?[]:p))))||null }
  async run(sql,p=[]) { const q=this.db.prepare(sql); const b=q.bind?q.bind(...p):q; return b.run(...(q.bind?[]:p)) }
  async findIdentity(a,b,c){const x=await this.one('SELECT * FROM identity_mappings WHERE provider=? AND provider_app_id=? AND provider_subject_hash=?',[a,b,c]);return x&&{provider:x.provider,providerAppId:x.provider_app_id,providerSubjectHash:x.provider_subject_hash,subjectId:x.subject_id,createdAt:x.created_at,lastSeenAt:x.last_seen_at}}
  async saveIdentity(x){return this.run('INSERT OR REPLACE INTO identity_mappings VALUES(?,?,?,?,?,?)',[x.provider,x.providerAppId,x.providerSubjectHash,x.subjectId,x.createdAt,x.lastSeenAt])}
  async resolveOrCreateIdentity({mapping,subject}){await this.run('INSERT OR IGNORE INTO subjects VALUES(?,?,?,?,?,?,?)',[subject.subjectId,subject.publicId,subject.status,subject.internal?1:0,subject.createdAt,subject.lastSeenAt,subject.identityVersion]);await this.run('INSERT OR IGNORE INTO identity_mappings VALUES(?,?,?,?,?,?)',[mapping.provider,mapping.providerAppId,mapping.providerSubjectHash,mapping.subjectId,mapping.createdAt,mapping.lastSeenAt]);const canonical=await this.findIdentity(mapping.provider,mapping.providerAppId,mapping.providerSubjectHash);return {subject:await this.getSubject(canonical.subjectId),created:canonical.createdAt===mapping.createdAt}}
  async getSubject(id){const x=await this.one('SELECT * FROM subjects WHERE id=?',[id]);return x&&{subjectId:x.id,publicId:x.public_id,status:x.status,internal:Boolean(x.internal),createdAt:x.created_at,lastSeenAt:x.last_seen_at,identityVersion:x.identity_version}}
  async saveSubject(x){return this.run('INSERT OR REPLACE INTO subjects VALUES(?,?,?,?,?,?,?)',[x.subjectId,x.publicId,x.status,x.internal?1:0,x.createdAt,x.lastSeenAt,x.identityVersion])}
  async publicIdExists(id){return Boolean(await this.one('SELECT id FROM subjects WHERE public_id=?',[id]))}
  async saveSession(h,x){return this.run('INSERT OR REPLACE INTO sessions VALUES(?,?,?,?,?)',[h,x.subjectId,x.issuedAt,x.expiresAt,x.revokedAt])}
  async getSession(h){const x=await this.one('SELECT * FROM sessions WHERE token_hash=?',[h]);return x&&{subjectId:x.subject_id,issuedAt:x.issued_at,expiresAt:x.expires_at,revokedAt:x.revoked_at}}
  async revokeSession(h,at){return this.run('UPDATE sessions SET revoked_at=? WHERE token_hash=?',[at,h])}
  async saveBindingCode(h,x){return this.run('INSERT OR REPLACE INTO binding_codes VALUES(?,?,?,?,?,?)',[h,x.subjectId,x.createdAt,x.expiresAt,x.usedAt,x.failedAttempts])}
  async getBindingCode(h){const x=await this.one('SELECT * FROM binding_codes WHERE code_hash=?',[h]);return x&&{subjectId:x.subject_id,createdAt:x.created_at,expiresAt:x.expires_at,usedAt:x.used_at,failedAttempts:x.failed_attempts}}
  async consumeBindingCode(h,at){const x=await this.getBindingCode(h);if(!x||x.usedAt)return false;await this.run('UPDATE binding_codes SET used_at=? WHERE code_hash=? AND used_at IS NULL',[at,h]);return true}
}
